import { quote } from "../../../pull/util.js";
function member(value) {
    return /^[A-Za-z_$][A-Za-z0-9_$]*$/.test(value) ? `.${value}` : `[${quote(value)}]`;
}
function property(value) {
    return /^[A-Za-z_$][A-Za-z0-9_$]*$/.test(value) ? value : quote(value);
}
function objectExpr(object, refs) {
    const resolved = object.kind === "element"
        ? refs.foreignElementRefNames?.get(object.name)
        : refs.foreignAppRefNames?.get(object.name);
    return `catalog${member(resolved ?? object.refName)}`;
}
function actionExpr(action, owner, refs) {
    switch (action.kind) {
        case "agent": return `flowAgentAction(catalog${member(owner)}.agents${member(action.refName)}${action.name !== undefined ? `, ${quote(action.name)}` : ""})`;
        case "automation": return `flowAutomationAction(catalog${member(owner)}.automations${member(action.refName)}${action.name !== undefined ? `, ${quote(action.name)}` : ""})`;
        case "user": return `flowUserAction(${quote(action.name)})`;
        case "api": return `flowApiAction(${quote(action.name)})`;
        case "object": return `flowObjectAction(${objectExpr(action.object, refs)}${action.name !== undefined ? `, ${quote(action.name)}` : ""})`;
    }
}
function nodeLines(node, owner, refs) {
    const lines = [
        `symbol: visualFlowSymbol.${node.symbol.toLowerCase()},`,
        `x: ${node.x},`,
        `y: ${node.y},`,
    ];
    if (node.description !== undefined)
        lines.push(`description: ${quote(node.description)},`);
    if (node.sourcePosition !== undefined)
        lines.push(`sourcePosition: visualFlowPosition.${node.sourcePosition.toLowerCase()},`);
    if (node.targetPosition !== undefined)
        lines.push(`targetPosition: visualFlowPosition.${node.targetPosition.toLowerCase()},`);
    if (node.connectsTo !== undefined) {
        lines.push(`connectsTo: [${node.connectsTo.map((connection) => connection.label === undefined ? quote(connection.target) : `{ target: ${quote(connection.target)}, label: ${quote(connection.label)} }`).join(", ")}],`);
    }
    if (node.action !== undefined)
        lines.push(`action: ${actionExpr(node.action, owner, refs)},`);
    if (node.target !== undefined)
        lines.push(`target: flowObjectTarget(${objectExpr(node.target.object, refs)}${node.target.name !== undefined ? `, ${quote(node.target.name)}` : ""}),`);
    return lines;
}
export function printVisualFlow(flow, owner, scope, refs = {}) {
    const used = new Set(["visualFlow", "visualFlowSymbol"]);
    for (const stage of flow.stages) {
        for (const node of Object.values(stage.nodes)) {
            if (node.sourcePosition !== undefined || node.targetPosition !== undefined)
                used.add("visualFlowPosition");
            if (node.target !== undefined)
                used.add("flowObjectTarget");
            if (node.action !== undefined) {
                used.add({
                    agent: "flowAgentAction",
                    automation: "flowAutomationAction",
                    user: "flowUserAction",
                    api: "flowApiAction",
                    object: "flowObjectAction",
                }[node.action.kind]);
            }
        }
    }
    const importOrder = [
        "visualFlow",
        "flowAgentAction",
        "flowApiAction",
        "flowAutomationAction",
        "flowObjectAction",
        "flowObjectTarget",
        "flowUserAction",
        "visualFlowPosition",
        "visualFlowSymbol",
    ];
    const lines = [
        "/** Auto-generated by EDK pull. Hand-edit freely. */",
        `import { ${importOrder.filter((name) => used.has(name)).join(", ")} } from "@elementumai/edk/visualFlows";`,
        'import catalog from "@catalog";',
        "",
        "export default visualFlow({",
        `  ${scope}: catalog${member(owner)},`,
        "  stages: {",
    ];
    for (const stage of flow.stages) {
        lines.push(`    ${property(stage.stage)}: {`, "      nodes: {");
        for (const [key, node] of Object.entries(stage.nodes)) {
            lines.push(`        ${property(key)}: {`, ...nodeLines(node, owner, refs).map((line) => `          ${line}`), "        },");
        }
        lines.push("      },", "    },");
    }
    lines.push("  },", "});", "");
    return lines.join("\n");
}
